// Smoke test: measured input → O-SSM → output conf ≤ 0.965 (asserted B dominates)

fn sqrt_t(x: f64) -> f64 with Mut, Div, Panic {
    if x <= 0.0 { return 0.0 }
    var y = x; var i = 0
    while i < 10 { y = 0.5 * (y + x / y); i = i + 1 }
    y
}
fn abs_t(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }
fn exp_t(x: f64) -> f64 with Mut, Div, Panic {
    if x > 20.0 { return exp_t(10.0) * exp_t(x - 10.0) }
    if x < 0.0 - 20.0 { return 0.0 }
    var s = 1.0; var t = 1.0; var i = 1
    while i <= 15 { t = t * x / (i as f64); s = s + t; i = i + 1 }
    s
}
fn sig_t(x: f64) -> f64 with Mut, Div, Panic { 1.0 / (1.0 + exp_t(0.0 - x)) }

struct Oct { e: [f64; 8] }
fn oct_mul(a: &Oct, b: &Oct) -> Oct with Mut, Div, Panic {
    var o: [f64; 8] = [0.0; 8]
    o[0] = a.e[0]*b.e[0]-a.e[1]*b.e[1]-a.e[2]*b.e[2]-a.e[3]*b.e[3]-a.e[4]*b.e[4]-a.e[5]*b.e[5]-a.e[6]*b.e[6]-a.e[7]*b.e[7]
    o[1] = a.e[0]*b.e[1]+a.e[1]*b.e[0]+a.e[2]*b.e[3]-a.e[3]*b.e[2]+a.e[4]*b.e[5]-a.e[5]*b.e[4]-a.e[6]*b.e[7]+a.e[7]*b.e[6]
    o[2] = a.e[0]*b.e[2]+a.e[2]*b.e[0]-a.e[1]*b.e[3]+a.e[3]*b.e[1]+a.e[4]*b.e[6]-a.e[6]*b.e[4]+a.e[5]*b.e[7]-a.e[7]*b.e[5]
    o[3] = a.e[0]*b.e[3]+a.e[3]*b.e[0]+a.e[1]*b.e[2]-a.e[2]*b.e[1]+a.e[4]*b.e[7]-a.e[7]*b.e[4]-a.e[5]*b.e[6]+a.e[6]*b.e[5]
    o[4] = a.e[0]*b.e[4]+a.e[4]*b.e[0]-a.e[1]*b.e[5]+a.e[5]*b.e[1]-a.e[2]*b.e[6]+a.e[6]*b.e[2]-a.e[3]*b.e[7]+a.e[7]*b.e[3]
    o[5] = a.e[0]*b.e[5]+a.e[5]*b.e[0]+a.e[1]*b.e[4]-a.e[4]*b.e[1]-a.e[2]*b.e[7]+a.e[7]*b.e[2]+a.e[3]*b.e[6]-a.e[6]*b.e[3]
    o[6] = a.e[0]*b.e[6]+a.e[6]*b.e[0]+a.e[1]*b.e[7]-a.e[7]*b.e[1]+a.e[2]*b.e[4]-a.e[4]*b.e[2]-a.e[3]*b.e[5]+a.e[5]*b.e[3]
    o[7] = a.e[0]*b.e[7]+a.e[7]*b.e[0]-a.e[1]*b.e[6]+a.e[6]*b.e[1]-a.e[2]*b.e[5]+a.e[5]*b.e[2]+a.e[3]*b.e[4]-a.e[4]*b.e[3]
    Oct { e: o }
}

struct EK { val: f64, unc: f64, conf: f64 }
fn ek_measured(v: f64, u: f64) -> EK { EK { val: v, unc: u, conf: 0.985 } }

fn main() -> i32 with IO, Mut, Div, Panic {
    // One SSM step: h = sigmoid(A ⊗ 0 + B * x)
    let A = Oct { e: [0.2, 0.1, 0.3, 0.0 - 0.1, 0.0, 0.15, 0.0 - 0.2, 0.05] }
    let B = Oct { e: [0.3, 0.0 - 0.2, 0.1, 0.25, 0.0 - 0.1, 0.0, 0.2, 0.0 - 0.15] }
    let C = Oct { e: [0.25, 0.1, 0.0 - 0.1, 0.2, 0.05, 0.0 - 0.2, 0.15, 0.1] }
    let x  = ek_measured(0.5, 0.01)    // measured input

    // Bx = B * x.val; h = sigmoid(Bx)
    var bx: [f64; 8] = [0.0; 8]; var i = 0
    while i < 8 { bx[i as usize] = B.e[i as usize] * x.val; i = i + 1 }
    var h: [f64; 8] = [0.0; 8]; i = 0
    while i < 8 { h[i as usize] = sig_t(bx[i as usize]); i = i + 1 }
    let h_oct = Oct { e: h }

    // y = Re(C ⊗ h)
    let Ch = oct_mul(&C, &h_oct)
    let y_val = Ch.e[0]

    // B is asserted (conf=0.965), input is measured (conf=0.985)
    // output conf = min(B_conf, x_conf) = min(0.965, 0.985) = 0.965
    var out_conf = 0.965
    if x.conf < out_conf { out_conf = x.conf }

    if abs_t(y_val) > 0.0 && out_conf <= 0.965 + 0.001 {
        println("ossm_knowledge_basic: PASS")
        return 0
    }
    println("ossm_knowledge_basic: FAIL")
    return 1
}

//@ run-pass
//@ requires: madaros
//@ description: Tiny PB/Cardinality at-most-two bridge checker

fn pb_bool_valid(x: i64) -> i64 {
    if x == 0 { return 1 }
    if x == 1 { return 1 }
    if x == (0 - 1) { return 1 }
    return 0
}

fn pb_min_term(w: i64, x: i64) -> i64 {
    if x == 1 { return w }
    return 0
}

fn pb_min_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_min_term(w0, x0) + pb_min_term(w1, x1) + pb_min_term(w2, x2)
}

fn pb_check_le_contradiction3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_min_sum3(w0, x0, w1, x1, w2, x2) > rhs { return 1 }
    return 0
}

fn pb_check_at_most_two_true_conflict3(x0: i64, x1: i64, x2: i64) -> i64 {
    return pb_check_le_contradiction3(1, x0, 1, x1, 1, x2, 2)
}

fn card_var(slot: i64) -> i64 {
    return slot + 1
}

fn card_valid_slot(n: i64, slot: i64) -> i64 {
    if slot < 0 { return 0 }
    if slot >= n { return 0 }
    return 1
}

fn card_at_most_two_clause_count(n: i64) -> i64 {
    if n < 3 { return 0 }
    return (n * (n - 1) * (n - 2)) / 6
}

fn card_at_most_two_clause_id(n: i64, a: i64, b: i64, c: i64) -> i64 {
    if card_valid_slot(n, a) == 0 { return 0 - 1 }
    if card_valid_slot(n, b) == 0 { return 0 - 1 }
    if card_valid_slot(n, c) == 0 { return 0 - 1 }
    if a == b { return 0 - 1 }
    if a == c { return 0 - 1 }
    if b == c { return 0 - 1 }

    var id: i64 = 1
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            var k: i64 = j + 1
            while k < n {
                var hit: i64 = 0
                if i == a {
                    if j == b {
                        if k == c { hit = 1 }
                    }
                    if j == c {
                        if k == b { hit = 1 }
                    }
                }
                if i == b {
                    if j == a {
                        if k == c { hit = 1 }
                    }
                    if j == c {
                        if k == a { hit = 1 }
                    }
                }
                if i == c {
                    if j == a {
                        if k == b { hit = 1 }
                    }
                    if j == b {
                        if k == a { hit = 1 }
                    }
                }
                if hit == 1 { return id }
                id = id + 1
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return 0 - 1
}

fn card_at_most_two_clause_len(n: i64, clause_id: i64) -> i64 {
    if clause_id < 1 { return 0 }
    if clause_id <= card_at_most_two_clause_count(n) { return 3 }
    return 0
}

fn card_at_most_two_lit(n: i64, clause_id: i64, pos: i64) -> i64 {
    if pos < 0 { return 0 }
    if pos >= 3 { return 0 }
    if card_at_most_two_clause_len(n, clause_id) != 3 { return 0 }

    var id: i64 = 1
    var i: i64 = 0
    while i < n {
        var j: i64 = i + 1
        while j < n {
            var k: i64 = j + 1
            while k < n {
                if id == clause_id {
                    if pos == 0 { return 0 - card_var(i) }
                    if pos == 1 { return 0 - card_var(j) }
                    return 0 - card_var(k)
                }
                id = id + 1
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return 0
}

fn card_lit_matches_one3(clause_lit: i64, lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if clause_lit + lit_a == 0 { return 1 }
    if clause_lit + lit_b == 0 { return 1 }
    if clause_lit + lit_c == 0 { return 1 }
    return 0
}

fn card_verify_at_most_two_conflict(n: i64, clause_id: i64, lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if lit_a <= 0 { return 0 }
    if lit_b <= 0 { return 0 }
    if lit_c <= 0 { return 0 }
    if lit_a == lit_b { return 0 }
    if lit_a == lit_c { return 0 }
    if lit_b == lit_c { return 0 }

    let a = lit_a - 1
    let b = lit_b - 1
    let c = lit_c - 1
    if card_valid_slot(n, a) == 0 { return 0 }
    if card_valid_slot(n, b) == 0 { return 0 }
    if card_valid_slot(n, c) == 0 { return 0 }
    if card_at_most_two_clause_id(n, a, b, c) != clause_id { return 0 }

    let c0 = card_at_most_two_lit(n, clause_id, 0)
    let c1 = card_at_most_two_lit(n, clause_id, 1)
    let c2 = card_at_most_two_lit(n, clause_id, 2)
    if card_lit_matches_one3(c0, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(c1, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(c2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return 1
}

fn pb_card_at_most_two_clause_matches3(clause_lit0: i64, clause_lit1: i64, clause_lit2: i64,
                                       lit_a: i64, lit_b: i64, lit_c: i64) -> i64 {
    if lit_a <= 0 { return 0 }
    if lit_b <= 0 { return 0 }
    if lit_c <= 0 { return 0 }
    if lit_a == lit_b { return 0 }
    if lit_a == lit_c { return 0 }
    if lit_b == lit_c { return 0 }
    if clause_lit0 >= 0 { return 0 }
    if clause_lit1 >= 0 { return 0 }
    if clause_lit2 >= 0 { return 0 }
    if clause_lit0 == clause_lit1 { return 0 }
    if clause_lit0 == clause_lit2 { return 0 }
    if clause_lit1 == clause_lit2 { return 0 }
    if card_lit_matches_one3(clause_lit0, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(clause_lit1, lit_a, lit_b, lit_c) == 0 { return 0 }
    if card_lit_matches_one3(clause_lit2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return 1
}

fn pb_check_card_at_most_two_clause_conflict3(clause_lit0: i64, clause_lit1: i64, clause_lit2: i64,
                                             lit_a: i64, lit_b: i64, lit_c: i64,
                                             x0: i64, x1: i64, x2: i64) -> i64 {
    if pb_card_at_most_two_clause_matches3(clause_lit0, clause_lit1, clause_lit2, lit_a, lit_b, lit_c) == 0 { return 0 }
    return pb_check_at_most_two_true_conflict3(x0, x1, x2)
}

fn bridge_at_most_two_conflict(n: i64, clause_id: i64, lit_a: i64, lit_b: i64, lit_c: i64,
                               x0: i64, x1: i64, x2: i64) -> i64 {
    if card_verify_at_most_two_conflict(n, clause_id, lit_a, lit_b, lit_c) == 0 { return 0 }
    let c0: i64 = card_at_most_two_lit(n, clause_id, 0)
    let c1: i64 = card_at_most_two_lit(n, clause_id, 1)
    let c2: i64 = card_at_most_two_lit(n, clause_id, 2)
    return pb_check_card_at_most_two_clause_conflict3(c0, c1, c2, lit_a, lit_b, lit_c, x0, x1, x2)
}

fn main() -> i64 {
    // In n=4, clause 4 is (-x2 OR -x3 OR -x4). PB view: x2+x3+x4 <= 2.
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 1, 1) != 1 { return 1 }
    if bridge_at_most_two_conflict(4, 4, 4, 2, 3, 1, 1, 1) != 1 { return 2 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 3, 0 - 4, 2, 3, 4) != 1 { return 11 }
    if pb_check_card_at_most_two_clause_conflict3(0 - 2, 0 - 3, 0 - 4, 2, 3, 4, 1, 1, 1) != 1 { return 12 }

    // The cardinality clause alone is not enough: the PB contradiction requires
    // three true assignments, so two true plus unknown is not certified.
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 1, 0 - 1) != 0 { return 3 }
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 1, 0) != 0 { return 4 }
    if pb_check_card_at_most_two_clause_conflict3(0 - 2, 0 - 3, 0 - 4, 2, 3, 4, 1, 1, 0 - 1) != 0 { return 13 }

    // The PB row alone is not enough either: wrong IDs, repeated lits, signs, or
    // out-of-range variables must fail before the arithmetic certificate is used.
    if bridge_at_most_two_conflict(4, 3, 2, 3, 4, 1, 1, 1) != 0 { return 5 }
    if bridge_at_most_two_conflict(4, 4, 2, 2, 4, 1, 1, 1) != 0 { return 6 }
    if bridge_at_most_two_conflict(4, 4, 2, 3, 0 - 4, 1, 1, 1) != 0 { return 7 }
    if bridge_at_most_two_conflict(4, 4, 2, 3, 5, 1, 1, 1) != 0 { return 8 }
    if bridge_at_most_two_conflict(2, 1, 1, 2, 3, 1, 1, 1) != 0 { return 9 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 2, 0 - 4, 2, 3, 4) != 0 { return 14 }
    if pb_card_at_most_two_clause_matches3(2, 0 - 3, 0 - 4, 2, 3, 4) != 0 { return 15 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 3, 0 - 5, 2, 3, 4) != 0 { return 16 }
    if pb_card_at_most_two_clause_matches3(0 - 2, 0 - 3, 0 - 4, 2, 2, 4) != 0 { return 17 }

    // Bad PB assignments are rejected rather than certified.
    if bridge_at_most_two_conflict(4, 4, 2, 3, 4, 1, 2, 1) != 0 { return 10 }

    return 0
}

//@ run-pass
//@ description: Tiny pseudo-Boolean proof-checker smoke

fn pb_bool_valid(x: i64) -> i64 {
    if x == 0 { return 1 }
    if x == 1 { return 1 }
    if x == (0 - 1) { return 1 }
    return 0
}

fn pb_min_term(w: i64, x: i64) -> i64 {
    if x == 1 { return w }
    return 0
}

fn pb_max_term(w: i64, x: i64) -> i64 {
    if x == 0 { return 0 }
    return w
}

fn pb_min_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_min_term(w0, x0) + pb_min_term(w1, x1) + pb_min_term(w2, x2)
}

fn pb_max_sum3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64) -> i64 {
    return pb_max_term(w0, x0) + pb_max_term(w1, x1) + pb_max_term(w2, x2)
}

fn pb_check_le_contradiction3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_min_sum3(w0, x0, w1, x1, w2, x2) > rhs { return 1 }
    return 0
}

fn pb_check_ge_contradiction3(w0: i64, x0: i64, w1: i64, x1: i64, w2: i64, x2: i64, rhs: i64) -> i64 {
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if pb_bool_valid(x0) == 0 { return 0 }
    if pb_bool_valid(x1) == 0 { return 0 }
    if pb_bool_valid(x2) == 0 { return 0 }
    if pb_max_sum3(w0, x0, w1, x1, w2, x2) < rhs { return 1 }
    return 0
}

fn pb_check_exactly_one_false_conflict3(x0: i64, x1: i64, x2: i64) -> i64 {
    return pb_check_ge_contradiction3(1, x0, 1, x1, 1, x2, 1)
}

fn pb_check_at_most_one_true_conflict3(x0: i64, x1: i64, x2: i64) -> i64 {
    return pb_check_le_contradiction3(1, x0, 1, x1, 1, x2, 1)
}

fn pb_saturate_coeff(w: i64, rhs: i64) -> i64 {
    if w < 0 { return 0 - 1 }
    if rhs < 0 { return 0 - 1 }
    if w > rhs { return rhs }
    return w
}

fn pb_check_saturation3(w0: i64, w1: i64, w2: i64, rhs: i64,
                        s0: i64, s1: i64, s2: i64) -> i64 {
    if rhs < 0 { return 0 }
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if s0 != pb_saturate_coeff(w0, rhs) { return 0 }
    if s1 != pb_saturate_coeff(w1, rhs) { return 0 }
    if s2 != pb_saturate_coeff(w2, rhs) { return 0 }
    return 1
}

fn pb_floor_div_nonneg(n: i64, divisor: i64) -> i64 with Div {
    if n < 0 { return 0 - 1 }
    if divisor <= 0 { return 0 - 1 }
    return n / divisor
}

fn pb_ceil_div_nonneg(n: i64, divisor: i64) -> i64 with Div {
    if n < 0 { return 0 - 1 }
    if divisor <= 0 { return 0 - 1 }
    return (n + divisor - 1) / divisor
}

fn pb_check_divide_le3(w0: i64, w1: i64, w2: i64, rhs: i64, divisor: i64,
                       q0: i64, q1: i64, q2: i64, qrhs: i64) -> i64 with Div {
    if divisor <= 0 { return 0 }
    if rhs < 0 { return 0 }
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if q0 != pb_floor_div_nonneg(w0, divisor) { return 0 }
    if q1 != pb_floor_div_nonneg(w1, divisor) { return 0 }
    if q2 != pb_floor_div_nonneg(w2, divisor) { return 0 }
    if qrhs != pb_floor_div_nonneg(rhs, divisor) { return 0 }
    return 1
}

fn pb_check_divide_ge3(w0: i64, w1: i64, w2: i64, rhs: i64, divisor: i64,
                       q0: i64, q1: i64, q2: i64, qrhs: i64) -> i64 with Div {
    if divisor <= 0 { return 0 }
    if rhs < 0 { return 0 }
    if w0 < 0 { return 0 }
    if w1 < 0 { return 0 }
    if w2 < 0 { return 0 }
    if q0 != pb_ceil_div_nonneg(w0, divisor) { return 0 }
    if q1 != pb_ceil_div_nonneg(w1, divisor) { return 0 }
    if q2 != pb_ceil_div_nonneg(w2, divisor) { return 0 }
    if qrhs != pb_ceil_div_nonneg(rhs, divisor) { return 0 }
    return 1
}

fn main() -> i64 with Div {
    if pb_min_sum3(2, 1, 3, 0 - 1, 5, 0) != 2 { return 1 }
    if pb_max_sum3(2, 1, 3, 0 - 1, 5, 0) != 5 { return 2 }

    // 2*x0 + 3*x1 + 5*x2 <= 4 is impossible once x0=x1=true.
    if pb_check_le_contradiction3(2, 1, 3, 1, 5, 0 - 1, 4) != 1 { return 3 }
    if pb_check_le_contradiction3(2, 1, 3, 0 - 1, 5, 0, 4) != 0 { return 4 }

    // 2*x0 + 3*x1 + 5*x2 >= 6 is impossible once x0=x1=x2=false.
    if pb_check_ge_contradiction3(2, 0, 3, 0, 5, 0, 6) != 1 { return 5 }
    if pb_check_ge_contradiction3(2, 0 - 1, 3, 0, 5, 0, 2) != 0 { return 6 }

    // Exactly-one contradiction: all three false violates sum >= 1.
    if pb_check_exactly_one_false_conflict3(0, 0, 0) != 1 { return 7 }
    if pb_check_exactly_one_false_conflict3(0, 0 - 1, 0) != 0 { return 8 }

    // At-most-one contradiction: two true literals force sum > 1.
    if pb_check_at_most_one_true_conflict3(1, 1, 0) != 1 { return 9 }
    if pb_check_at_most_one_true_conflict3(1, 0 - 1, 0) != 0 { return 10 }

    // Bad assignments and negative weights are rejected rather than certified.
    if pb_check_le_contradiction3(1, 2, 1, 1, 1, 1, 1) != 0 { return 11 }
    if pb_check_le_contradiction3(0 - 1, 1, 1, 1, 1, 1, 1) != 0 { return 12 }

    // Saturation proof step: 5*x0 + 2*x1 + 7*x2 <= 3 saturates to
    // 3*x0 + 2*x1 + 3*x2 <= 3 for Boolean variables.
    if pb_saturate_coeff(5, 3) != 3 { return 13 }
    if pb_saturate_coeff(2, 3) != 2 { return 14 }
    if pb_check_saturation3(5, 2, 7, 3, 3, 2, 3) != 1 { return 15 }
    if pb_check_saturation3(5, 2, 7, 3, 5, 2, 3) != 0 { return 16 }
    if pb_check_saturation3(5, 2, 7, 0 - 1, 0, 0, 0) != 0 { return 17 }

    // Use the saturated inequality as a checked arithmetic certificate.
    // Under x0=x1=true, even the saturated minimum is 5 > 3.
    if pb_check_le_contradiction3(3, 1, 2, 1, 3, 0 - 1, 3) != 1 { return 18 }

    // Division proof steps. A <= row divides with floor rounding:
    // 5*x0 + 2*x1 + 7*x2 <= 8  ==>  2*x0 + 1*x1 + 3*x2 <= 4.
    if pb_floor_div_nonneg(7, 2) != 3 { return 19 }
    if pb_check_divide_le3(5, 2, 7, 8, 2, 2, 1, 3, 4) != 1 { return 20 }
    if pb_check_divide_le3(5, 2, 7, 8, 2, 3, 1, 3, 4) != 0 { return 21 }

    // A >= row divides with ceil rounding:
    // 5*x0 + 2*x1 + 7*x2 >= 9  ==>  3*x0 + 1*x1 + 4*x2 >= 5.
    if pb_ceil_div_nonneg(7, 2) != 4 { return 22 }
    if pb_check_divide_ge3(5, 2, 7, 9, 2, 3, 1, 4, 5) != 1 { return 23 }
    if pb_check_divide_ge3(5, 2, 7, 9, 2, 2, 1, 4, 5) != 0 { return 24 }
    if pb_check_divide_ge3(5, 2, 7, 9, 0, 3, 1, 4, 5) != 0 { return 25 }
    if pb_check_divide_le3(0 - 1, 2, 7, 8, 2, 0, 1, 3, 4) != 0 { return 26 }

    return 0
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout-contains: PBPK28_THETA_CLOSED_SYSTEM_MASS_PASS

// Madaros-qualified twin of pbpk28_theta_closed_system_mass.sio (identical
// body). The full suite runs lean_single; this copy puts the same θ /
// Rannacher / TR-BDF2 / routing checks in front of
// scripts/ci/madaros_changed_tests_gate.sh, because theta_pbpk28.sio carries
// Madaros-specific workarounds (in-place &! stepping, element-wise stage
// copies). Keep the two bodies in sync.

// Closed-system mass witness for stdlib/darwin_pbpk/theta_pbpk28.sio.
//
// With cl_central = 0 and no input, total body mass must stay at the dose.
// The published CN kernel (`pbpk28_full_cn_step`) does not: its negativity
// floors turn the sign-alternating stiff modes a bolus excites into mass —
// venlafaxine parent, 50 mg into blood, dt = 0.5 h: 85.065244 mg after one
// step, 89.100032 mg after eight. That kernel is left untouched for its
// parity gates; this test pins the clamp-free replacement:
//
//   1. Rannacher (2 start-up steps), TR-BDF2 and plain clamp-free CN keep
//      M_n = M_0 at every step, three drug profiles, dt ∈ {0.5, 0.1, 0.05} h.
//   2. Rannacher and TR-BDF2 book no visible negative mass in any returned
//      state (CN alone would: it rings to −9 mg/L here, which is why it is not
//      the production path). TR-BDF2's internal stage x_γ is printed as
//      stage_neg_mass and not gated.
//   3. With central clearance and an organ sink (venlafaxine CYP2D6 formation
//      clearance on the liver, CL_form·dt/V_liver ≈ 12 at dt = 0.5 h), the
//      ledger identity M(T) + eliminated + sink_removed − administered = M(0)
//      closes to rounding under a constant input.
//   4. The same with the input routed into the liver's vascular space
//      (portal first-pass, input_organ = 1): the identity still closes, and
//      routing through the liver raises the liver AUC over blood input.
//
// Bounds (theta_pbpk28 gate functions): |ΔM|/M_0 ≤ max(1e-12, steps·1e-15),
// a heuristic rounding budget for an identity that is exact in real
// arithmetic; booked negative mass ≤ 5e-7 mg, half the last digit of a
// 6-decimal mg print.

use darwin_pbpk::core::pbpk28_params::*
use darwin_pbpk::theta_pbpk28::*

fn t_abs(x: f64) -> f64 { if x < 0.0 { 0.0 - x } else { x } }

// method: 0 = clamp-free CN, 1 = Rannacher, 2 = TR-BDF2
fn t_step(method: i32, st: &!PBPKState28, p: PBPKParams28, dt: f64, k: i32, led: &!PBPK28Ledger) with Mut, Div {
    if method == 0 {
        pbpk28_theta_step_mut(st, p, 0.0, dt, 0.5, led)
    } else {
        if method == 1 {
            pbpk28_rannacher_step_mut(st, p, 0.0, dt, k < pbpk28_rannacher_startup_steps(), led)
        } else {
            pbpk28_trbdf2_step_mut(st, p, 0.0, dt, led)
        }
    }
}

// Returns 1 on failure. Prints the worst per-step drift (x 1e12).
fn t_closed(tag: string, p0: PBPKParams28, dose: f64, dt: f64, nsteps: i32, method: i32, check_neg: bool) -> i32 with IO, Mut, Div {
    var p = p0
    p.cl_central = 0.0
    var st = pbpk28_state_zero()
    st.cv[0] = dose / p.v_ref[0]
    let m0 = pbpk28_total_mass(st, p)
    var led = pbpk28_ledger_zero()
    var worst = 0.0
    var ok = true
    var k: i32 = 0
    while k < nsteps {
        t_step(method, &!st, p, dt, k, &!led)
        let drift = t_abs(pbpk28_total_mass(st, p) - m0) / m0
        // NaN compares false against every bound: reject it explicitly.
        if drift != drift { ok = false }
        if drift > worst { worst = drift }
        if drift > pbpk28_mass_tol_rel(led.steps) { ok = false }
        k = k + 1
    }
    if check_neg && led.neg_mass > pbpk28_neg_mass_bound_mg() { ok = false }
    print(tag)
    print(" method=")
    print(method)
    print(" dt=")
    print(dt)
    print(" worst|dM|/M0 x1e12=")
    print(worst * 1.0e12)
    print(" M_end=")
    print(pbpk28_total_mass(st, p))
    print(" neg_mass x1e12=")
    print(led.neg_mass * 1.0e12)
    // TR-BDF2's internal stage x_γ: reported, not gated (it is not a returned
    // state; after a bolus its CN stage rings negative by design).
    print(" stage_neg_mass x1e12=")
    println(led.stage_neg_mass * 1.0e12)
    if ok { return 0 }
    println("  FAIL")
    return 1
}

fn t_profiles(dt: f64, nsteps: i32) -> i32 with IO, Mut, Div {
    var f: i32 = 0
    var m: i32 = 0
    while m < 3 {
        // CN alone conserves mass but rings negative: gate conservation only.
        let neg = m > 0
        f = f + t_closed("venlafaxine_parent", pbpk28_params_venlafaxine_parent(), 50.0, dt, nsteps, m, neg)
        f = f + t_closed("rapamycin", pbpk28_params_rapamycin(), 5.0, dt, nsteps, m, neg)
        f = f + t_closed("semaglutide", pbpk28_params_semaglutide(), 1.0, dt, nsteps, m, neg)
        m = m + 1
    }
    return f
}

// Open system: central CL + liver organ sink + constant input, 48 h.
fn t_sink(method: i32, dt: f64) -> i32 with IO, Mut, Div {
    let p = pbpk28_params_venlafaxine_parent()
    var st = pbpk28_state_zero()
    var led = pbpk28_ledger_zero()
    let cl_form = 43.0      // NM CYP2D6 formation clearance, L/h (Klamerus 1999)
    let rel = 3.0           // mg/h into blood
    var t = 0.0
    var k: i32 = 0
    while t < 48.0 - 0.5 * dt {
        if method == 1 {
            let _s = pbpk28_rannacher_step_sink_mut(&!st, p, rel, dt, k < pbpk28_rannacher_startup_steps(), 1, cl_form, &!led)
        } else {
            let _s = pbpk28_trbdf2_step_sink_mut(&!st, p, rel, dt, 1, cl_form, &!led)
        }
        t = t + dt
        k = k + 1
    }
    let r = pbpk28_ledger_residual(led, st, p, 0.0)
    if r != r {
        println("  FAIL: NaN residual")
        return 1
    }
    print("sink method=")
    print(method)
    print(" dt=")
    print(dt)
    print(" administered=")
    print(led.administered)
    print(" sink_removed=")
    print(led.sink_removed)
    print(" eliminated=")
    print(led.eliminated)
    print(" |res|/admin x1e12=")
    println(t_abs(r) / led.administered * 1.0e12)
    if t_abs(r) <= pbpk28_mass_tol_rel(led.steps) * led.administered && led.sink_removed > 0.0 {
        return 0
    }
    println("  FAIL")
    return 1
}

// Input routed into organ `route` (0 = blood). Returns the liver AUC, or −1
// when the ledger identity does not close.
fn t_route_run(method: i32, route: i32, dt: f64) -> f64 with IO, Mut, Div {
    let p = pbpk28_params_venlafaxine_parent()
    var st = pbpk28_state_zero()
    var led = pbpk28_ledger_zero()
    let cl_form = 43.0
    let rel = 3.0
    var t = 0.0
    var k: i32 = 0
    while t < 48.0 - 0.5 * dt {
        if method == 1 {
            // Rannacher: BE half-step pairs for the start-up, routed CN after.
            let _s = pbpk28_rannacher_step_routed_sink_mut(&!st, p, rel, route, dt, k < pbpk28_rannacher_startup_steps(), 1, cl_form, &!led)
        } else {
            let _s = pbpk28_trbdf2_step_routed_sink_mut(&!st, p, rel, route, dt, 1, cl_form, &!led)
        }
        t = t + dt
        k = k + 1
    }
    let r = pbpk28_ledger_residual(led, st, p, 0.0)
    if r != r { return 0.0 - 1.0 }
    print("route method=")
    print(method)
    print(" input_organ=")
    print(route)
    print(" sink_removed=")
    print(led.sink_removed)
    print(" auc_liver=")
    print(led.auc[1])
    print(" |res|/admin x1e12=")
    println(t_abs(r) / led.administered * 1.0e12)
    if t_abs(r) > pbpk28_mass_tol_rel(led.steps) * led.administered { return 0.0 - 1.0 }
    if led.neg_mass > pbpk28_neg_mass_bound_mg() { return 0.0 - 1.0 }
    return led.auc[1]
}

fn t_route(method: i32) -> i32 with IO, Mut, Div {
    let a_blood = t_route_run(method, 0, 0.5)
    let a_liver = t_route_run(method, 1, 0.5)
    if a_blood >= 0.0 && a_liver > a_blood { return 0 }
    println("  FAIL")
    return 1
}

// Input routed into a vascular space below the degenerate-volume floor
// (liver vasc_frac = 0): the step must refuse it -- inject nothing, book it
// as rejected_input rather than administered -- so the identity closes and
// the mass gate fails. `no_outflow` also zeroes the liver's Q and PS: that is
// the configuration where, before the refusal, all 12 mg booked were lost
// (residual -12 mg); with the liver's flows the input passed through and the
// identity closed (see p28t_route_rejected in theta_pbpk28.sio).
fn t_route_degenerate(method: i32, no_outflow: bool) -> i32 with IO, Mut, Div {
    var p = pbpk28_params_venlafaxine_parent()
    p.vasc_frac[1] = 0.0
    if no_outflow {
        p.q[1] = 0.0
        p.ps[1] = 0.0
    }
    var st = pbpk28_state_zero()
    var led = pbpk28_ledger_zero()
    let rel = 3.0
    let dt = 0.5
    var k: i32 = 0
    while k < 8 {
        if method == 1 {
            let _s = pbpk28_rannacher_step_routed_sink_mut(&!st, p, rel, 1, dt, k < pbpk28_rannacher_startup_steps(), 0, 0.0, &!led)
        } else {
            let _s = pbpk28_trbdf2_step_routed_sink_mut(&!st, p, rel, 1, dt, 0, 0.0, &!led)
        }
        k = k + 1
    }
    let r = pbpk28_ledger_residual(led, st, p, 0.0)
    let gate = pbpk28_mass_gate_ok(led, st, p, 0.0, 12.0)
    print("degenerate route method=")
    print(method)
    if no_outflow { print(" no_outflow") }
    print(" administered=")
    print(led.administered)
    print(" rejected_input=")
    print(led.rejected_input)
    print(" |res| x1e12=")
    println(t_abs(r) * 1.0e12)
    if led.administered == 0.0 && led.rejected_input == 12.0 && t_abs(r) <= 1.0e-12 && !gate { return 0 }
    println("  FAIL")
    return 1
}

fn main() -> i32 with IO, Mut, Div {
    var failed: i32 = 0
    failed = failed + t_profiles(0.5, 8)
    failed = failed + t_profiles(0.1, 40)
    failed = failed + t_profiles(0.05, 80)
    failed = failed + t_sink(1, 0.5)
    failed = failed + t_sink(2, 0.5)
    failed = failed + t_route(1)
    failed = failed + t_route(2)
    failed = failed + t_route_degenerate(1, false)
    failed = failed + t_route_degenerate(2, false)
    failed = failed + t_route_degenerate(1, true)
    failed = failed + t_route_degenerate(2, true)
    if failed == 0 {
        println("PBPK28_THETA_CLOSED_SYSTEM_MASS_PASS")
    } else {
        print("failed=")
        println(failed)
    }
    return failed
}

//@ run-pass
// PK Domain Uncertainty Plugin Test Suite
//
// Validates WS2 Track 5 — PK-specific uncertainty analysis:
//   1.  Clearance dominance detection (CL contributes >70%)
//   2.  Volume dominance detection (V contributes most)
//   3.  Balanced contributions (no single dominant)
//   4.  SCr as proxy for clearance (Cockcroft-Gault scenario)
//   5.  Sensitivity index S_Ti > 0.7 triggers clearance dominance flag
//   6.  PK recommendations: clearance dominant -> TDM
//   7.  PK recommendations: absorption dominant -> bioequivalence
//   8.  Clinical significance: uncertainty > therapeutic window
//   9.  Clinical significance: uncertainty < therapeutic window
//  10.  Edge case: single parameter is 100% dominant
//  11.  Recommendation for SCr dominant -> cystatin C
//  12.  Sensitivity indices sum to 1.0
//
// Reference: Saltelli et al. (2008), FDA PopPK Guidance (2022)

// ============================================================================
// HELPERS
// ============================================================================

fn abs_val(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn sqrt_val(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    if guess < 0.001 { guess = 0.001 }
    var i = 0
    while i < 30 {
        guess = (guess + x / guess) / 2.0
        i = i + 1
    }
    return guess
}

// ============================================================================
// FLAT PKProfile STRUCT
// No nested structs — all parameter data in flat arrays.
// ============================================================================

struct PKProfile {
    n_params: i64,
    p_code: [i64; 8],
    p_value: [f64; 8],
    p_std_uncert: [f64; 8],
    p_sensitivity: [f64; 8],
    p_contribution: [f64; 8],
    p_source_type: [i64; 8],
    combined_variance: f64,
    combined_std_uncert: f64,
    clearance_contribution: f64,
    volume_contribution: f64,
    absorption_contribution: f64,
    is_cl_dominant: i64,
    dominant_idx: i64,
    dominant_pct: f64,
    r0: i64,
    r1: i64,
    r2: i64,
    r3: i64,
    n_rec: i64
}

fn empty_profile() -> PKProfile {
    PKProfile {
        n_params: 0,
        p_code: [0; 8],
        p_value: [0.0; 8],
        p_std_uncert: [0.0; 8],
        p_sensitivity: [0.0; 8],
        p_contribution: [0.0; 8],
        p_source_type: [0; 8],
        combined_variance: 0.0,
        combined_std_uncert: 0.0,
        clearance_contribution: 0.0,
        volume_contribution: 0.0,
        absorption_contribution: 0.0,
        is_cl_dominant: 0,
        dominant_idx: 0,
        dominant_pct: 0.0,
        r0: 0, r1: 0, r2: 0, r3: 0,
        n_rec: 0
    }
}

fn set_param(profile: PKProfile, idx: i64, code: i64, value: f64, std_uncert: f64, sensitivity: f64, source_type: i64) -> PKProfile with Mut {
    var r = profile
    let contrib = sensitivity * sensitivity * std_uncert * std_uncert
    r.p_code[idx as usize] = code
    r.p_value[idx as usize] = value
    r.p_std_uncert[idx as usize] = std_uncert
    r.p_sensitivity[idx as usize] = sensitivity
    r.p_contribution[idx as usize] = contrib
    r.p_source_type[idx as usize] = source_type
    return r
}

// ============================================================================
// FLAT PKSens STRUCT
// ============================================================================

struct PKSens {
    s_ti: [f64; 8],
    s_i: [f64; 8],
    n_params: i64,
    dom_idx: i64,
    dom_s_ti: f64,
    cl_dominant: i64
}

fn empty_sens() -> PKSens {
    PKSens {
        s_ti: [0.0; 8],
        s_i: [0.0; 8],
        n_params: 0,
        dom_idx: 0,
        dom_s_ti: 0.0,
        cl_dominant: 0
    }
}

// ============================================================================
// PARAMETER CLASSIFICATION
// ============================================================================

fn is_cl(code: i64) -> bool {
    if code == 0 { return true }
    if code == 3 { return true }
    if code == 7 { return true }
    if code == 6 { return true }
    return false
}

fn is_vol(code: i64) -> bool {
    if code == 1 { return true }
    if code == 6 { return true }
    return false
}

fn is_abs(code: i64) -> bool {
    if code == 2 { return true }
    if code == 4 { return true }
    return false
}

// ============================================================================
// ANALYSIS FUNCTIONS
// ============================================================================

fn compute_contributions(profile: PKProfile, n: i64) -> PKProfile with Mut, Div {
    var r = profile
    r.n_params = n

    var total: f64 = 0.0
    var i = 0
    while i < n {
        total = total + r.p_contribution[i as usize]
        i = i + 1
    }

    r.combined_variance = total
    r.combined_std_uncert = sqrt_val(total)

    if total < 1.0e-15 {
        return r
    }

    var cl: f64 = 0.0
    var v: f64 = 0.0
    var ab: f64 = 0.0
    var best_idx = 0
    var best_pct: f64 = 0.0

    i = 0
    while i < n {
        let contrib = r.p_contribution[i as usize]
        let code = r.p_code[i as usize]
        let pct = 100.0 * contrib / total

        if pct > best_pct {
            best_pct = pct
            best_idx = i
        }
        if is_cl(code) { cl = cl + pct }
        if is_vol(code) { v = v + pct }
        if is_abs(code) { ab = ab + pct }

        i = i + 1
    }

    r.clearance_contribution = cl
    r.volume_contribution = v
    r.absorption_contribution = ab
    r.dominant_idx = best_idx
    r.dominant_pct = best_pct

    if cl > 70.0 {
        r.is_cl_dominant = 1
    } else {
        r.is_cl_dominant = 0
    }

    return r
}

fn compute_sensitivity(profile: PKProfile, n: i64) -> PKSens with Mut, Div {
    var r = empty_sens()
    r.n_params = n

    var total: f64 = 0.0
    var i = 0
    while i < n {
        total = total + profile.p_contribution[i as usize]
        i = i + 1
    }

    if total < 1.0e-15 {
        return r
    }

    var best_idx = 0
    var best_s_ti: f64 = 0.0

    i = 0
    while i < n {
        let s_ti = profile.p_contribution[i as usize] / total
        r.s_ti[i as usize] = s_ti
        r.s_i[i as usize] = s_ti
        if s_ti > best_s_ti {
            best_s_ti = s_ti
            best_idx = i
        }
        i = i + 1
    }

    r.dom_idx = best_idx
    r.dom_s_ti = best_s_ti

    var cl_total: f64 = 0.0
    i = 0
    while i < n {
        if is_cl(profile.p_code[i as usize]) {
            cl_total = cl_total + profile.p_contribution[i as usize] / total
        }
        i = i + 1
    }

    if cl_total > 0.7 {
        r.cl_dominant = 1
    } else {
        r.cl_dominant = 0
    }

    return r
}

fn generate_rec(profile: PKProfile) -> PKProfile with Mut, Div {
    var r = profile
    var n_rec = 0

    if profile.is_cl_dominant != 0 {
        if n_rec == 0 { r.r0 = 10 }
        else if n_rec == 1 { r.r1 = 10 }
        else if n_rec == 2 { r.r2 = 10 }
        else if n_rec == 3 { r.r3 = 10 }
        n_rec = n_rec + 1
    }

    if profile.volume_contribution > 50.0 {
        if n_rec == 0 { r.r0 = 11 }
        else if n_rec == 1 { r.r1 = 11 }
        else if n_rec == 2 { r.r2 = 11 }
        else if n_rec == 3 { r.r3 = 11 }
        n_rec = n_rec + 1
    }

    if profile.absorption_contribution > 50.0 {
        if n_rec == 0 { r.r0 = 12 }
        else if n_rec == 1 { r.r1 = 12 }
        else if n_rec == 2 { r.r2 = 12 }
        else if n_rec == 3 { r.r3 = 12 }
        n_rec = n_rec + 1
    }

    if profile.is_cl_dominant != 0 {
        var scr_pct: f64 = 0.0
        var i = 0
        while i < profile.n_params {
            if profile.p_code[i as usize] == 7 {
                if profile.combined_variance > 1.0e-15 {
                    scr_pct = 100.0 * profile.p_contribution[i as usize] / profile.combined_variance
                }
            }
            i = i + 1
        }
        if scr_pct > 20.0 {
            if n_rec < 4 {
                if n_rec == 0 { r.r0 = 13 }
                else if n_rec == 1 { r.r1 = 13 }
                else if n_rec == 2 { r.r2 = 13 }
                else if n_rec == 3 { r.r3 = 13 }
                n_rec = n_rec + 1
            }
        }
    }

    if profile.combined_std_uncert > 0.0 {
        let dom_val = profile.p_value[profile.dominant_idx as usize]
        if abs_val(dom_val) > 1.0e-15 {
            let rel_uncert = 100.0 * profile.combined_std_uncert / abs_val(dom_val)
            if rel_uncert > 30.0 {
                if n_rec < 4 {
                    if n_rec == 0 { r.r0 = 14 }
                    else if n_rec == 1 { r.r1 = 14 }
                    else if n_rec == 2 { r.r2 = 14 }
                    else if n_rec == 3 { r.r3 = 14 }
                    n_rec = n_rec + 1
                }
            }
        }
    }

    if n_rec > 4 { r.n_rec = 4 } else { r.n_rec = n_rec }
    return r
}

fn pk_analyze(profile: PKProfile, n: i64) -> PKProfile with Mut, Div {
    var r = compute_contributions(profile, n)
    r = generate_rec(r)
    return r
}

fn is_clinically_sig(profile: PKProfile, tw: f64) -> i64 with Div {
    if tw <= 1.0 { return 1 }
    let half_width = 2.0 * profile.combined_std_uncert
    let dom_val = profile.p_value[profile.dominant_idx as usize]
    if abs_val(dom_val) < 1.0e-15 { return 1 }
    let rel_half = half_width / abs_val(dom_val)
    let margin = 1.0 - 1.0 / tw
    if rel_half > margin { return 1 }
    return 0
}

