fn expr_print(node_idx: i64) with IO, Mut, Panic, Div {
    let ntype = SYMA.node_types[node_idx]

    if ntype == 0 {
        print(SYMA.values[node_idx])
        return
    }
    if ntype == 1 {
        let vi = SYMA.values[node_idx] as i64
        if vi == 0 { print("x") }
        else if vi == 1 { print("y") }
        else if vi == 2 { print("z") }
        else { print("v"); print(vi) }
        return
    }
    if ntype == 2 {
        print("(")
        expr_print(SYMA.left[node_idx])
        print(" + ")
        expr_print(SYMA.right[node_idx])
        print(")")
        return
    }
    if ntype == 3 {
        print("(")
        expr_print(SYMA.left[node_idx])
        print(" - ")
        expr_print(SYMA.right[node_idx])
        print(")")
        return
    }
    if ntype == 4 {
        print("(")
        expr_print(SYMA.left[node_idx])
        print(" * ")
        expr_print(SYMA.right[node_idx])
        print(")")
        return
    }
    if ntype == 5 {
        print("(")
        expr_print(SYMA.left[node_idx])
        print(" / ")
        expr_print(SYMA.right[node_idx])
        print(")")
        return
    }
    if ntype == 6 {
        print("(-")
        expr_print(SYMA.left[node_idx])
        print(")")
        return
    }
    if ntype == 7 {
        print("sin(")
        expr_print(SYMA.left[node_idx])
        print(")")
        return
    }
    if ntype == 8 {
        print("cos(")
        expr_print(SYMA.left[node_idx])
        print(")")
        return
    }
    if ntype == 9 {
        print("exp(")
        expr_print(SYMA.left[node_idx])
        print(")")
        return
    }
    if ntype == 10 {
        print("ln(")
        expr_print(SYMA.left[node_idx])
        print(")")
        return
    }
    if ntype == 11 {
        print("(")
        expr_print(SYMA.left[node_idx])
        print("^")
        print(SYMA.values[node_idx])
        print(")")
        return
    }
    print("?")
}

